using System.Collections;
using Astrea.BattleActions;
using LittleLeo;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "HatchingChrysalisEffect", menuName = "Data/Battle/Effects/Enemy/WitheredChrysalis Effect")]
public class HatchingChrysalisEffect : Effect
{
	[Header("Withered Chrysalis")]
	[SerializeField]
	private DefaultEffectAction serenityAction;

	[SerializeField]
	private Effect purifySensitive;

	[SerializeField]
	private float delayToVFX = 0.5f;

	[SerializeField]
	private float delayToSFX = 0.5f;

	[SerializeField]
	private float delayAfterAnimation = 0.8f;

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), amount, base.localizationManager.GetLocalizedEnemyEffectOwnerReceiveEffectFormatted(purifySensitive, 1)) + "\n" + base.localizationManager.GetLocalizedAtTheEndOfEnemiesTurn(withSpace: true) + base.localizationManager.GetLocalizedLoseAllEffect(purifySensitive).LowercaseFirst();
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<UnitEffects>();
		effectOwner.GetComponent<UnitEffects>().IsEffectActiveGetAmountAndDecreaseEffect(this, 1);
		RemoveAllPurifySensitive(effectOwner);
		if (effectAmount == 1)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(LeaveCocoonAnimation(effectOwner));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		return effectAmount;
	}

	private IEnumerator LeaveCocoonAnimation(GameObject effectOwner)
	{
		CorruptedAnimalSpriteControl corruptedAnimalSpriteControl = effectOwner.GetComponent<CorruptedAnimalSpriteControl>();
		corruptedAnimalSpriteControl.TweenStripeEffect(0.4f, CoroutineUtility.LinearCurve(), 0f);
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, delayToSFX, delegate
		{
			PlayEffectActivationSFX();
		});
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, delayToVFX, delegate
		{
			SpawnVFX(GetVFXOwnerPosition(effectOwner), 10f);
		});
		yield return ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(corruptedAnimalSpriteControl.PlayAnimationForcedCoroutine(AnimationType.Skill, AnimationChangeType.StayInTheNewAnimationNotLooping, delegate
		{
			corruptedAnimalSpriteControl.PlayAnimation(AnimationType.Idle, AnimationChangeType.StayInTheNewAnimationLooping);
			corruptedAnimalSpriteControl.TweenStripeEffect(0.5f, CoroutineUtility.LinearCurve(), 1f);
		}));
		yield return new WaitForSeconds(delayAfterAnimation);
	}

	public void IncreaseSerenity(GameObject effectOwner)
	{
		serenityAction.CastTargetAmount(effectOwner, 1, null);
	}

	public void RemoveAllPurifySensitive(GameObject effectOwner)
	{
		effectOwner.GetComponent<UnitEffects>().RemoveEffect(purifySensitive);
	}
}
